"use client";
import { useEffect, useRef } from "react";
import L from "leaflet";
import "leaflet/dist/leaflet.css";

// fix: ícones do default marker quebram com bundlers (caminho relativo perdido)
delete (L.Icon.Default.prototype as { _getIconUrl?: unknown })._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: "https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon-2x.png",
  iconUrl: "https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png",
  shadowUrl: "https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png",
});

export function BasicMap() {
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!ref.current) return;
    const map = L.map(ref.current, {
      center: [-23.5505, -46.6333],
      zoom: 12,
      preferCanvas: true, // canvas renderer global — chave para perf
    });

    L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
      attribution: "© OpenStreetMap contributors",
      maxZoom: 19,
      detectRetina: true, // baixa @2x onde disponível
    }).addTo(map);

    L.marker([-23.5505, -46.6333])
      .addTo(map)
      .bindPopup("São Paulo");

    return () => { map.remove(); };
  }, []);

  return <div ref={ref} style={{ width: "100%", height: 480 }} />;
}

import "leaflet.markercluster";
import "leaflet.markercluster/dist/MarkerCluster.css";
import "leaflet.markercluster/dist/MarkerCluster.Default.css";

// cria cluster — config tuned para 50k+ markers
const cluster = L.markerClusterGroup({
  chunkedLoading: true,           // carrega em chunks de 200 — não trava UI
  chunkInterval: 200,
  chunkDelay: 50,
  removeOutsideVisibleBounds: true, // não renderiza markers fora do viewport
  spiderfyOnMaxZoom: true,        // em zoom máximo, espalha cluster em flor
  showCoverageOnHover: false,     // hover não desenha hull (custoso)
  maxClusterRadius: 60,           // px — menor = mais clusters menores
  disableClusteringAtZoom: 17,    // a partir de zoom 17 mostra individual
});

// adicionar 50.000 ocorrências (estilo eventos do 190 SP)
fetch("/api/ocorrencias.geojson")
  .then(r => r.json())
  .then((geojson: GeoJSON.FeatureCollection<GeoJSON.Point>) => {
    const markers = geojson.features.map(f => {
      const [lng, lat] = f.geometry.coordinates;
      return L.marker([lat, lng]).bindPopup(
        `<strong>${f.properties?.tipo}</strong><br/>${f.properties?.data}`
      );
    });
    cluster.addLayers(markers);
    map.addLayer(cluster);
  });

// Renderer canvas global (preferCanvas: true no map options)
const map = L.map(el, { preferCanvas: true });

// OU por layer (mais flexível)
const canvasRenderer = L.canvas({ padding: 0.5 });

fetch("/api/bairros.geojson")
  .then(r => r.json())
  .then((data: GeoJSON.FeatureCollection) => {
    L.geoJSON(data, {
      renderer: canvasRenderer,
      style: feature => ({
        color: "#84cc16",
        weight: 1,
        fillOpacity: 0.2,
        fillColor: feature?.properties?.cor ?? "#374151",
      }),
      onEachFeature: (feature, layer) => {
        // hover em canvas: feature precisa de eventos manualmente
        layer.on({
          mouseover: e => e.target.setStyle({ weight: 3 }),
          mouseout: e => e.target.setStyle({ weight: 1 }),
        });
      },
    }).addTo(map);
  });
